for (const locale of supportedLocales) Object.assign(dictionaries[locale], dashboardPolishWords[locale] || {});
for (const locale of supportedLocales) Object.assign(dictionaries[locale], dashboardWords[locale] || {}, legalWords[locale] || {}, dashboardExtraWords[locale] || {});

export function translate(locale, key) {
  return dictionaries[locale]?.[key] || dictionaries.en[key] || key;
}
export function setSiteLocale(locale) {
  if (!supportedLocales.includes(locale)) return;
  window.localStorage.setItem("vicehub-language", locale);
  document.documentElement.lang = locale;
  window.dispatchEvent(new Event("vicehub:languagechange"));
}
export function useLocale() {
  const [locale, setLocaleState] = useState("en");
  useEffect(() => {
    const sync = () => {
      const saved = window.localStorage.getItem("vicehub-language") || "en";
      setLocaleState(supportedLocales.includes(saved) ? saved : "en");
    };
    sync();
    window.addEventListener("vicehub:languagechange", sync);
    return () => window.removeEventListener("vicehub:languagechange", sync);
  }, []);
  return locale;
}
